#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_N 100
#define OFFSET 50
#define SIZE 101

int main() {
    char s[MAX_N + 1];
    int x, y;
    scanf("%s", s);
    scanf("%d %d", &x, &y);

    int n = strlen(s);

    // dp[i][dx][dy][dir] = reachable after i instructions at (dx, dy) facing dir
    // dir: 0 = +x, 1 = +y, 2 = -x, 3 = -y
    bool dp[MAX_N + 1][SIZE][SIZE][4];
    memset(dp, 0, sizeof(dp));

    dp[0][0 + OFFSET][0 + OFFSET][0] = true;

    for (int i = 0; i < n; i++) {
        for (int dx = -OFFSET; dx <= OFFSET; dx++) {
            for (int dy = -OFFSET; dy <= OFFSET; dy++) {
                for (int dir = 0; dir < 4; dir++) {
                    if (!dp[i][dx + OFFSET][dy + OFFSET][dir]) continue;

                    if (s[i] == 'F') {
                        int ndx = dx, ndy = dy;
                        if (dir == 0) ndx++;
                        else if (dir == 1) ndy++;
                        else if (dir == 2) ndx--;
                        else ndy--;
                        if (ndx >= -OFFSET && ndx <= OFFSET && ndy >= -OFFSET && ndy <= OFFSET) {
                            dp[i+1][ndx + OFFSET][ndy + OFFSET][dir] = true;
                        }
                    } else { // 'T'
                        // turn clockwise
                        dp[i+1][dx + OFFSET][dy + OFFSET][(dir + 1) % 4] = true;
                        // turn counterclockwise
                        dp[i+1][dx + OFFSET][dy + OFFSET][(dir + 3) % 4] = true;
                    }
                }
            }
        }
    }

    bool possible = false;
    for (int dir = 0; dir < 4; dir++) {
        if (dp[n][x + OFFSET][y + OFFSET][dir]) {
            possible = true;
            break;
        }
    }

    printf("%s\n", possible ? "Yes" : "No");

    return 0;
}

