#define MAXS 8005
#define OFFSET 8000
#define SIZE 16010

int main(void) {
    char s[MAXS];
    int x, y;

    if (scanf("%s", s) != 1) return 0;
    if (scanf("%d %d", &x, &y) != 2) return 0;

    int n = (int)strlen(s);
    int seg[MAXS];
    int cnt = 0;

    int i = 0;
    while (i < n) {
        if (s[i] == 'F') {
            int j = i;
            while (j < n && s[j] == 'F') j++;
            seg[cnt++] = j - i;
            i = j;
        } else {
            seg[cnt++] = 0; /* separator for T */
            i++;
        }
    }

    /* Extract lengths of consecutive F blocks separated by T */
    int runs[MAXS], rn = 0;
    int cur = 0;
    for (i = 0; i < n; i++) {
        if (s[i] == 'F') cur++;
        else {
            runs[rn++] = cur;
            cur = 0;
        }
    }
    runs[rn++] = cur;

    /* runs[0] is forced movement along +x before first T */
    int xmoves[MAXS], ynmoves[MAXS];
    int xn = 0, yn = 0;

    for (i = 1; i < rn; i++) {
        if (i % 2 == 1) xmoves[xn++] = runs[i];
        else ynmoves[yn++] = runs[i];
    }

    static char dpX[SIZE], nextX[SIZE];
    static char dpY[SIZE], nextY[SIZE];

    memset(dpX, 0, sizeof(dpX));
    memset(dpY, 0, sizeof(dpY));

    int startX = runs[0];
    if (startX + OFFSET >= 0 && startX + OFFSET < SIZE)
        dpX[startX + OFFSET] = 1;
    dpY[OFFSET] = 1;

    for (i = 0; i < xn; i++) {
        memset(nextX, 0, sizeof(nextX));
        int d = xmoves[i];
        for (int p = 0; p < SIZE; p++) {
            if (!dpX[p]) continue;
            if (p + d < SIZE) nextX[p + d] = 1;
            if (p - d >= 0) nextX[p - d] = 1;
        }
        memcpy(dpX, nextX, sizeof(dpX));
    }

    for (i = 0; i < yn; i++) {
        memset(nextY, 0, sizeof(nextY));
        int d = ynmoves[i];
        for (int p = 0; p < SIZE; p++) {
            if (!dpY[p]) continue;
            if (p + d < SIZE) nextY[p + d] = 1;
            if (p - d >= 0) nextY[p - d] = 1;
        }
        memcpy(dpY, nextY, sizeof(dpY));
    }

    if (x + OFFSET >= 0 && x + OFFSET < SIZE &&
        y + OFFSET >= 0 && y + OFFSET < SIZE &&
        dpX[x + OFFSET] && dpY[y + OFFSET]) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }

    return 0;
}

