public class RobotPath {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int x = sc.nextInt();
        int y = sc.nextInt();
        sc.close();

        // Directions: 0=+x, 1=+y, 2=-x, 3=-y
        int[] dx = {1, 0, -1, 0};
        int[] dy = {0, 1, 0, -1};

        // Set of possible states (x, y, dir)
        Set<String> states = new HashSet<>();
        states.add("0,0,0"); // start at origin facing +x

        for (char c : s.toCharArray()) {
            Set<String> nextStates = new HashSet<>();
            for (String state : states) {
                String[] parts = state.split(",");
                int cx = Integer.parseInt(parts[0]);
                int cy = Integer.parseInt(parts[1]);
                int dir = Integer.parseInt(parts[2]);

                if (c == 'F') {
                    int nx = cx + dx[dir];
                    int ny = cy + dy[dir];
                    nextStates.add(nx + "," + ny + "," + dir);
                } else { // 'T'
                    // turn clockwise
                    nextStates.add(cx + "," + cy + "," + ((dir + 1) % 4));
                    // turn counterclockwise
                    nextStates.add(cx + "," + cy + "," + ((dir + 3) % 4));
                }
            }
            states = nextStates;
        }

        for (String state : states) {
            String[] parts = state.split(",");
            int fx = Integer.parseInt(parts[0]);
            int fy = Integer.parseInt(parts[1]);
            if (fx == x && fy == y) {
                System.out.println("Yes");
                return;
            }
        }
        System.out.println("No");
    }
}

