public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int tx = sc.nextInt();
        int ty = sc.nextInt();

        // directions: 0=East(+x), 1=North(+y), 2=West(-x), 3=South(-y)
        int[] dx = {1, 0, -1, 0};
        int[] dy = {0, 1, 0, -1};

        // State: (x, y, dir) encoded
        // Use a set of long encoded states
        Set<Long> current = new HashSet<>();
        current.add(encode(0, 0, 0));

        int n = s.length();

        for (char c : s.toCharArray()) {
            Set<Long> next = new HashSet<>();
            for (long state : current) {
                int[] decoded = decode(state);
                int x = decoded[0], y = decoded[1], d = decoded[2];
                if (c == 'F') {
                    next.add(encode(x + dx[d], y + dy[d], d));
                } else { // T
                    next.add(encode(x, y, (d + 1) % 4));
                    next.add(encode(x, y, (d + 3) % 4));
                }
            }
            current = next;
        }

        boolean found = false;
        for (long state : current) {
            int[] decoded = decode(state);
            if (decoded[0] == tx && decoded[1] == ty) {
                found = true;
                break;
            }
        }

        System.out.println(found ? "Yes" : "No");
    }

    static long encode(int x, int y, int d) {
        // offset x and y by 10000 to handle negatives
        return ((long)(x + 10000)) * 100000000L + ((long)(y + 10000)) * 10L + d;
    }

    static int[] decode(long val) {
        int d = (int)(val % 10);
        val /= 10;
        int y = (int)(val % 100000) - 10000;
        val /= 100000;
        int x = (int)(val) - 10000;
        return new int[]{x, y, d};
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String s = fs.next();
        int x = fs.nextInt();
        int y = fs.nextInt();

        List<Integer> xs = new ArrayList<>();
        List<Integer> ys = new ArrayList<>();

        int n = s.length();
        int i = 0;

        // Initial consecutive F's move only in +x direction.
        int initialX = 0;
        while (i < n && s.charAt(i) == 'F') {
            initialX++;
            i++;
        }

        // Parse remaining runs of F separated by T's.
        // After the initial direction (+x), movement alternates:
        // y, x, y, x, ...
        int axis = 0; // 0 -> next F-run is on y-axis, 1 -> x-axis
        while (i < n) {
            // skip one or more T's; only parity matters for axis switching
            int tCount = 0;
            while (i < n && s.charAt(i) == 'T') {
                tCount++;
                i++;
            }
            axis ^= (tCount % 2);

            int cnt = 0;
            while (i < n && s.charAt(i) == 'F') {
                cnt++;
                i++;
            }
            if (cnt > 0) {
                if (axis == 0) ys.add(cnt);
                else xs.add(cnt);
            }
        }

        boolean canX = reachable(xs, x - initialX);
        boolean canY = reachable(ys, y);

        System.out.println((canX && canY) ? "Yes" : "No");
    }

    static boolean reachable(List<Integer> moves, int target) {
        Set<Integer> cur = new HashSet<>();
        cur.add(0);

        for (int d : moves) {
            Set<Integer> next = new HashSet<>();
            for (int v : cur) {
                next.add(v + d);
                next.add(v - d);
            }
            cur = next;
        }
        return cur.contains(target);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

def solve():
    s = input().strip()
    x, y = map(int, input().split())

    # dp set contains tuples (x, y, direction)
    # direction: 0 = +x, 1 = +y, 2 = -x, 3 = -y
    dp = {(0, 0, 0)}

    for ch in s:
        new_dp = set()
        if ch == 'F':
            for cx, cy, d in dp:
                if d == 0:
                    new_dp.add((cx + 1, cy, d))
                elif d == 1:
                    new_dp.add((cx, cy + 1, d))
                elif d == 2:
                    new_dp.add((cx - 1, cy, d))
                else:
                    new_dp.add((cx, cy - 1, d))
        else:  # 'T'
            for cx, cy, d in dp:
                new_dp.add((cx, cy, (d + 1) % 4))
                new_dp.add((cx, cy, (d - 1) % 4))
        dp = new_dp

    for cx, cy, _ in dp:
        if cx == x and cy == y:
            print("Yes")
            return
    print("No")

if __name__ == "__main__":
    solve()
